// create-job.ts
import { randomUUID } from 'node:crypto'

type Job = { id: string; key: string; payload: string; createdAt: string }
type Db = {
  findByKey(key: string): Promise<Job | null>
  insert(job: Job): Promise<void> // rejects with { code: 'UNIQUE_KEY' } on a key race
}

const cache = new Map<string, Job>()

export async function createJob(
  db: Db,
  input: { key: string; payload: unknown },
  now = () => new Date()
): Promise<Omit<Job, 'payload'>> {
  const withoutPayload = (job: Job): Omit<Job, 'payload'> => ({
    id: job.id,
    key: job.key,
    createdAt: job.createdAt,
  })

  const key = input.key.trim()
  if (!key) {
    throw new Error('Invalid key: trimmed key must not be empty')
  }

  const serializedPayload = JSON.stringify(input.payload) as string | undefined
  if (serializedPayload === undefined) {
    throw new Error('Invalid payload: JSON.stringify returned undefined')
  }

  const createdAt = now().toISOString()
  const id = randomUUID()
  const job: Job = {
    id,
    key,
    payload: serializedPayload,
    createdAt,
  }

  const existing = await db.findByKey(key)
  if (existing) {
    cache.set(key, existing)
    return withoutPayload(existing)
  }

  try {
    await db.insert(job)
    cache.set(key, job)
    return withoutPayload(job)
  } catch (error) {
    if (
      typeof error === 'object' &&
      error !== null &&
      (error as { code?: unknown }).code === 'UNIQUE_KEY'
    ) {
      const winner = await db.findByKey(key)
      if (winner) {
        cache.set(key, winner)
        return withoutPayload(winner)
      }
    }

    throw error
  }
}
