// create-job.test.ts
import { describe, expect, it, vi } from 'vitest'
import { createJob } from './create-job'

type PublicJob = { id: string; key: string; createdAt: string }
type StoredJob = PublicJob & { payload: string }

let keyCounter = 0
const uniqueKey = (prefix: string): string => {
  return `${prefix}-${++keyCounter}-${Math.random().toString(36).slice(2)}`
}

function deferred<T = void>() {
  let resolve!: (value: T | PromiseLike<T>) => void
  let reject!: (reason?: unknown) => void

  const promise = new Promise<T>((res, rej) => {
    resolve = res
    reject = rej
  })

  return { promise, resolve, reject }
}

function relevantCacheSets(spy: any, key: string): [unknown, unknown][] {
  return spy.mock.calls.filter((call: [unknown, unknown]) => call[0] === key)
}

const publicFields = (job: PublicJob): PublicJob => ({
  id: job.id,
  key: job.key,
  createdAt: job.createdAt,
})

describe('createJob', () => {
  it('rejects an empty trimmed key before serializing or touching the database', async () => {
    let stringifyCount = 0
    let counting = true

    const payload = {
      toJSON() {
        if (counting) stringifyCount++
        return 'x'
      },
    }

    let dbCalled = false
    const db = {
      findByKey: vi.fn(async () => {
        dbCalled = true
        return null
      }),
      insert: vi.fn(async () => {
        dbCalled = true
      }),
    } as any

    await expect(createJob(db, { key: '   ', payload })).rejects.toThrow(/empty/i)

    counting = false
    expect(stringifyCount).toBe(0)
    expect(dbCalled).toBe(false)
  })

  it('trims the key, captures one timestamp, serializes once, inserts it, and returns public fields', async () => {
    const key = uniqueKey('valid')

    let stringifyCount = 0
    let counting = true
    const payload = {
      toJSON() {
        if (counting) stringifyCount++
        return 'ok'
      },
    }

    const iso = new Date('2024-01-02T03:04:05.678Z').toISOString()
    let nowCalls = 0
    const now = () => {
      nowCalls++
      return new Date(iso)
    }

    let insertedJob: StoredJob | undefined
    const db = {
      findByKey: vi.fn(async () => null),
      insert: vi.fn(async (job: StoredJob) => {
        insertedJob = job
      }),
    } as any

    const result = await createJob(db, { key: `  ${key}  `, payload }, now)
    counting = false

    expect(stringifyCount).toBe(1)
    expect(nowCalls).toBe(1)

    expect(db.findByKey).toHaveBeenCalledWith(key)
    expect(insertedJob).toBeDefined()
    expect(insertedJob!.key).toBe(key)
    expect(typeof insertedJob!.payload).toBe('string')
    expect(insertedJob!.id).toEqual(expect.any(String))
    expect(insertedJob!.createdAt).toBe(iso)

    expect(result).not.toHaveProperty('payload')
    expect(Object.keys(result)).toHaveLength(3)
    expect(publicFields(result as PublicJob)).toEqual(publicFields(insertedJob!))
  })

  it('rejects when JSON.stringify returns undefined', async () => {
    let stringifyCount = 0
    let counting = true

    const payload = {
      toJSON() {
        if (counting) stringifyCount++
        return undefined as any
      },
    }

    let dbCalled = false
    const db = {
      findByKey: vi.fn(async () => {
        dbCalled = true
        return null
      }),
      insert: vi.fn(async () => {
        dbCalled = true
      }),
    } as any

    await expect(createJob(db, { key: uniqueKey('undefined-payload'), payload })).rejects.toThrow(
      /undefined/i
    )

    counting = false
    expect(stringifyCount).toBe(1)
    expect(dbCalled).toBe(false)
  })

  it('returns existing row from database and updates cache after confirmed read', async () => {
    const key = uniqueKey('existing')
    const existing: StoredJob = {
      id: 'existing-id',
      key,
      payload: 'existing-secret',
      createdAt: new Date('2020-01-01T00:00:00.000Z').toISOString(),
    }

    const db = {
      findByKey: vi.fn(async () => existing),
      insert: vi.fn(async () => {
        throw new Error('insert should not be called')
      }),
    } as any

    let cacheSetsBeforeRestore: [unknown, unknown][] = []
    const setSpy = vi.spyOn(Map.prototype, 'set')

    try {
      const result = await createJob(db, { key, payload: { x: 1 } })

      expect(result).not.toHaveProperty('payload')
      expect(publicFields(result as PublicJob)).toEqual({
        id: existing.id,
        key,
        createdAt: existing.createdAt,
      })

      cacheSetsBeforeRestore = relevantCacheSets(setSpy, key)
    } finally {
      setSpy.mockRestore()
    }

    expect(cacheSetsBeforeRestore).toHaveLength(1)
    expect((cacheSetsBeforeRestore[0][1] as StoredJob).id).toBe(existing.id)
    expect(db.insert).not.toHaveBeenCalled()
  })

  it('returns the database winner on UNIQUE_KEY and does not capture a second timestamp', async () => {
    const key = uniqueKey('unique-winner')
    const uniqueError = { code: 'UNIQUE_KEY' } as const

    let findByKeyCalls = 0
    const winner: StoredJob = {
      id: 'winner-id',
      key,
      payload: 'winner-secret',
      createdAt: new Date('2023-01-01T00:00:00.000Z').toISOString(),
    }

    const db = {
      findByKey: vi.fn(async () => {
        findByKeyCalls++
        return findByKeyCalls === 1 ? null : winner
      }),
      insert: vi.fn(async () => {
        throw uniqueError
      }),
    } as any

    let nowCalls = 0
    const now = () => {
      nowCalls++
      return new Date('2024-01-01T00:00:00.000Z')
    }

    const setSpy = vi.spyOn(Map.prototype, 'set')
    let result: PublicJob
    let cacheSetsAfterRestore: [unknown, unknown][]

    try {
      result = await createJob(db, { key, payload: {} }, now)
      cacheSetsAfterRestore = relevantCacheSets(setSpy, key)
    } finally {
      setSpy.mockRestore()
    }

    expect(nowCalls).toBe(1)
    expect(findByKeyCalls).toBeGreaterThanOrEqual(2)
    expect(result!.id).toBe(winner.id)
    expect(result!.key).toBe(key)
    expect(result!.createdAt).toBe(winner.createdAt)
    expect(cacheSetsAfterRestore.length).toBeGreaterThan(0)
  })

  it('does not update cache during a concurrent pending insert and returns one winner', async () => {
    const key = uniqueKey('concurrent')

    let committed: StoredJob | null = null
    let insertCalls = 0

    const firstInsertStarted = deferred<void>()
    const secondInsertStarted = deferred<void>()
    const releaseCommit = deferred<void>()

    const db = {
      findByKey: vi.fn(async () => committed),
      insert: vi.fn(async (job: StoredJob) => {
        insertCalls++

        if (insertCalls === 1) firstInsertStarted.resolve()
        if (insertCalls === 2) secondInsertStarted.resolve()

        await releaseCommit.promise

        if (committed) {
          throw { code: 'UNIQUE_KEY' }
        }

        committed = job
      }),
    } as any

    let p1: any
    let p2: any

    const setSpy = vi.spyOn(Map.prototype, 'set')

    try {
      p1 = createJob(db, { key, payload: { side: 'a' } })
      await firstInsertStarted.promise

      p2 = createJob(db, { key, payload: { side: 'b' } })
      await secondInsertStarted.promise

      // Both DB inserts are pending; the cache must not have changed for this key.
      expect(relevantCacheSets(setSpy, key)).toHaveLength(0)

      releaseCommit.resolve()

      const [result1, result2] = await Promise.all([p1, p2])
      const cacheCallsAfterSuccess = relevantCacheSets(setSpy, key)

      if (!committed) throw new Error('expected a winner row')

      expect(result1).toEqual(result2)
      expect(publicFields(result1)).toEqual(publicFields(committed))
      expect(publicFields(result2)).toEqual(publicFields(committed))
      expect(db.insert).toHaveBeenCalledTimes(2)
      expect(cacheCallsAfterSuccess.length).toBeGreaterThan(0)
    } finally {
      releaseCommit.resolve()
      p1?.catch(() => {})
      p2?.catch(() => {})
      setSpy.mockRestore()
    }
  })

  it('re-reads on UNIQUE_KEY and rethrows the original error when no winner exists', async () => {
    const key = uniqueKey('unique-missing')
    const uniqueError = { code: 'UNIQUE_KEY' } as const

    const db = {
      findByKey: vi.fn(async () => null),
      insert: vi.fn(async () => {
        throw uniqueError
      }),
    } as any

    let cacheSetCount = 0
    const setSpy = vi.spyOn(Map.prototype, 'set')

    try {
      await expect(createJob(db, { key, payload: {} })).rejects.toBe(uniqueError)
      cacheSetCount = relevantCacheSets(setSpy, key).length
    } finally {
      setSpy.mockRestore()
    }

    expect(db.findByKey).toHaveBeenCalledTimes(2)
    expect(cacheSetCount).toBe(0)
  })

  it('preserves non-unique database errors unchanged and does not update the cache', async () => {
    const key = uniqueKey('non-unique')
    const error = new Error('database down')

    const db = {
      findByKey: vi.fn(async () => null),
      insert: vi.fn(async () => {
        throw error
      }),
    } as any

    let cacheSetCount = 0
    const setSpy = vi.spyOn(Map.prototype, 'set')

    try {
      await expect(createJob(db, { key, payload: {} })).rejects.toBe(error)
      cacheSetCount = relevantCacheSets(setSpy, key).length
    } finally {
      setSpy.mockRestore()
    }

    expect(db.findByKey).toHaveBeenCalledTimes(1)
    expect(cacheSetCount).toBe(0)
  })
})
