// src/createJob.ts
import { randomUUID } from 'node:crypto';

type Job = { id: string; key: string; payload: string; createdAt: string };

type Db = {
  findByKey(key: string): Promise<Job | null>;
  insert(job: Job): Promise<void>; // rejects with { code: 'UNIQUE_KEY' } on a key race
};

const cache = new Map<string, Job>();

export async function createJob(
  db: Db,
  input: { key: string; payload: unknown },
  now = () => new Date()
): Promise<Omit<Job, 'payload'>> {
  if (typeof input.key !== 'string') {
    throw new Error('key must be a non-empty trimmed string');
  }

  const key = input.key.trim();
  if (!key) {
    throw new Error('key must be a non-empty trimmed string');
  }

  const payload = JSON.stringify(input.payload);
  if (payload === undefined) {
    throw new Error('payload could not be serialized to JSON');
  }

  const createdAt = now().toISOString();
  const id = randomUUID();
  const job: Job = { id, key, payload, createdAt };

  const publicJob = (value: Job): Omit<Job, 'payload'> => ({
    id: value.id,
    key: value.key,
    createdAt: value.createdAt,
  });

  const isUniqueKeyError = (error: unknown): boolean => {
    return error !== null && typeof error === 'object' && (error as { code?: unknown }).code === 'UNIQUE_KEY';
  };

  const existing = await db.findByKey(key);
  if (existing) {
    cache.set(key, existing);
    return publicJob(existing);
  }

  try {
    await db.insert(job);
  } catch (error) {
    if (!isUniqueKeyError(error)) {
      throw error;
    }

    const winner = await db.findByKey(key);
    if (!winner) {
      throw error;
    }

    cache.set(key, winner);
    return publicJob(winner);
  }

  cache.set(key, job);
  return publicJob(job);
}
