// src/createJob.test.ts
import { randomUUID } from 'node:crypto';
import { describe, expect, it, vi } from 'vitest';
import { createJob } from './createJob';

type LocalJob = {
  id: string;
  key: string;
  payload: string;
  createdAt: string;
};

function makeKey(): string {
  return `test-job-${randomUUID()}`;
}

function createGate(): { promise: Promise<void>; release: () => void } {
  let release!: () => void;
  const promise = new Promise<void>((resolve) => {
    release = resolve;
  });
  return { promise, release };
}

function countSetCallsFor(spy: any, key: string): number {
  return (spy.mock.calls as [unknown, unknown][]).filter((call) => call[0] === key).length;
}

describe('createJob', () => {
  it('rejects empty trimmed keys before DB or payload serialization', async () => {
    let stringifyCalls = 0;
    let findCalls = 0;
    let insertCalls = 0;

    const db = {
      async findByKey() {
        findCalls++;
        return null;
      },
      async insert(_job: LocalJob) {
        insertCalls++;
      },
    } as any;

    const payload = {
      toJSON() {
        stringifyCalls++;
        return 'ok';
      },
    };

    await expect(createJob(db, { key: '   ', payload })).rejects.toThrow(/key/i);

    expect(stringifyCalls).toBe(0);
    expect(findCalls).toBe(0);
    expect(insertCalls).toBe(0);
  });

  it('serializes payload exactly once and captures time exactly once', async () => {
    const key = makeKey();
    let stringifyCalls = 0;
    let nowCalls = 0;
    const inserted: LocalJob[] = [];

    const db = {
      async findByKey() {
        return null;
      },
      async insert(job: LocalJob) {
        inserted.push(job);
      },
    } as any;

    const payload = {
      toJSON() {
        stringifyCalls++;
        return { ok: true };
      },
    };

    const result = await createJob(
      db,
      { key, payload },
      () => {
        nowCalls++;
        return new Date('2024-01-01T00:00:00.000Z');
      }
    );

    expect(stringifyCalls).toBe(1);
    expect(nowCalls).toBe(1);

    expect(inserted.length).toBe(1);
    expect(inserted[0].key).toBe(key);
    expect(inserted[0].payload).toBe('{"ok":true}');

    expect(result.key).toBe(key);
    expect(result.createdAt).toBe('2024-01-01T00:00:00.000Z');
    expect(result).not.toHaveProperty('payload');
    expect(Object.keys(result).sort()).toEqual(['createdAt', 'id', 'key']);
  });

  it('rejects after one JSON.stringify call when stringify returns undefined', async () => {
    const key = makeKey();
    let stringifyCalls = 0;
    let findCalls = 0;

    const db = {
      async findByKey() {
        findCalls++;
        return null;
      },
      async insert(_job: LocalJob) {},
    } as any;

    const payload = function () {} as unknown as { toJSON(): undefined };
    (payload as any).toJSON = () => {
      stringifyCalls++;
      return undefined;
    };

    await expect(createJob(db, { key, payload })).rejects.toThrow(/payload/i);

    expect(stringifyCalls).toBe(1);
    expect(findCalls).toBe(0);
  });

  it('preserves non-unique database errors and does not re-read', async () => {
    const key = makeKey();
    const originalError = new Error('connection lost');
    let findCalls = 0;
    let insertCalls = 0;

    const db = {
      async findByKey() {
        findCalls++;
        return null;
      },
      async insert(_job: LocalJob) {
        insertCalls++;
        throw originalError;
      },
    } as any;

    let thrown: unknown;
    try {
      await createJob(db, { key, payload: 'x' });
    } catch (error) {
      thrown = error;
    }

    expect(thrown).toBe(originalError);
    expect(findCalls).toBe(1);
    expect(insertCalls).toBe(1);
  });

  it('re-reads on UNIQUE_KEY and rethrows the original unique error if no winner exists', async () => {
    const key = makeKey();
    const uniqueError = { code: 'UNIQUE_KEY' };
    let findCalls = 0;
    let insertCalls = 0;

    const db = {
      async findByKey() {
        findCalls++;
        return null;
      },
      async insert(_job: LocalJob) {
        insertCalls++;
        throw uniqueError;
      },
    } as any;

    let thrown: unknown;
    try {
      await createJob(db, { key, payload: 'x' });
    } catch (error) {
      thrown = error;
    }

    expect(thrown).toBe(uniqueError);
    expect(findCalls).toBe(2);
    expect(insertCalls).toBe(1);
  });

  it('is database-authoritative for repeated calls and does not insert twice', async () => {
    const key = makeKey();
    const store: Record<string, LocalJob> = {};
    let findCalls = 0;
    let insertCalls = 0;

    const db = {
      async findByKey(k: string) {
        findCalls++;
        return store[k] ?? null;
      },
      async insert(job: LocalJob) {
        insertCalls++;
        if (store[job.key]) {
          throw { code: 'UNIQUE_KEY' };
        }
        store[job.key] = job;
      },
    } as any;

    const first = await createJob(db, { key, payload: 'first' });

    expect(findCalls).toBe(1);
    expect(insertCalls).toBe(1);
    expect(first.key).toBe(key);
    expect(first).not.toHaveProperty('payload');

    const second = await createJob(db, { key, payload: 'ignored' });

    expect(findCalls).toBe(2);
    expect(insertCalls).toBe(1);
    expect(second.id).toBe(first.id);
    expect(second.key).toBe(key);
    expect(second.createdAt).toBe(first.createdAt);
    expect(second).not.toHaveProperty('payload');
  });

  it('does not update the cache before a pending insert succeeds', async () => {
    const key = makeKey();
    const insertGate = createGate();
    const insertStarted = createGate();
    const spy = vi.spyOn(Map.prototype, 'set');

    try {
      const insertedJobs: LocalJob[] = [];

      const db = {
        async findByKey() {
          return null;
        },
        insert(job: LocalJob) {
          insertedJobs.push(job);
          insertStarted.release();
          return insertGate.promise.then(() => undefined);
        },
      } as any;

      const resultPromise = createJob(db, { key, payload: 'x' });
      void resultPromise.catch(() => undefined);

      await insertStarted.promise;

      expect(countSetCallsFor(spy, key)).toBe(0);

      insertGate.release();

      const result = await resultPromise;
      expect(result.key).toBe(key);
      expect(result).not.toHaveProperty('payload');
      expect(insertedJobs.length).toBe(1);
      expect(countSetCallsFor(spy, key)).toBeGreaterThan(0);
    } finally {
      insertGate.release();
      vi.restoreAllMocks();
    }
  });

  it('handles a concurrent unique-key race and returns the database winner', async () => {
    const key = makeKey();
    const commitGate = createGate();
    const firstStarted = createGate();
    const secondStarted = createGate();
    const spy = vi.spyOn(Map.prototype, 'set');

    try {
      const store: Record<string, LocalJob> = {};
      let findCalls = 0;
      let insertCalls = 0;

      const db = {
        async findByKey(k: string) {
          findCalls++;
          return store[k] ?? null;
        },
        insert(job: LocalJob) {
          if (insertCalls === 0) {
            insertCalls++;
            firstStarted.release();

            return commitGate.promise.then(() => {
              store[job.key] = job;
            });
          }

          insertCalls++;
          secondStarted.release();

          return commitGate.promise.then(() => {
            throw { code: 'UNIQUE_KEY' };
          });
        },
      } as any;

      const p1 = createJob(db, { key, payload: 'first' });
      void p1.catch(() => undefined);

      await firstStarted.promise;

      const p2 = createJob(db, { key, payload: 'second' });
      void p2.catch(() => undefined);

      await secondStarted.promise;

      expect(countSetCallsFor(spy, key)).toBe(0);

      commitGate.release();

      const [r1, r2] = await Promise.all([p1, p2]);

      expect(findCalls).toBe(3);
