```ts
// createJob.ts — replace only the function body
export async function createJob(
  db: Db,
  input: { key: string; payload: unknown },
  now = () => new Date()
): Promise<Omit<Job, 'payload'>> {
  const key = input.key == null ? '' : String(input.key).trim();
  if (key === '') {
    throw new Error('key must not be empty');
  }

  const serializedPayload = JSON.stringify(input.payload);
  if (serializedPayload === undefined) {
    throw new Error('payload must serialize to a string');
  }

  const isUniqueKeyError = (error: unknown): boolean =>
    typeof error === 'object' &&
    error !== null &&
    (error as { code?: unknown }).code === 'UNIQUE_KEY';

  const publicJob = (job: Job): Omit<Job, 'payload'> => ({
    id: job.id,
    key,
    createdAt: job.createdAt,
  });

  const existing = await db.findByKey(key);
  if (existing) {
    cache.set(key, existing);
    return publicJob(existing);
  }

  const timestamp = now();
  const candidate: Job = {
    id: randomUUID(),
    key,
    payload: serializedPayload,
    createdAt: timestamp.toISOString(),
  };

  try {
    await db.insert(candidate);
    cache.set(key, candidate);
    return publicJob(candidate);
  } catch (error) {
    if (!isUniqueKeyError(error)) {
      throw error;
    }

    const winner = await db.findByKey(key);
    if (!winner) {
      throw error;
    }

    cache.set(key, winner);
    return publicJob(winner);
  }
}
