  findByKey(key: string): Promise<DbRow | null>
  insert(job: DbRow): Promise<void>
}

let suffix = 0
function makeKey(prefix: string): string {
  return `${prefix}-${++suffix}`
}

function isDbRow(value: unknown): value is DbRow {
  if (typeof value !== 'object' || value === null) return false

  const row = value as Record<string, unknown>
  return (
    typeof row.id === 'string' &&
    typeof row.key === 'string' &&
    typeof row.payload === 'string' &&
    typeof row.createdAt === 'string'
  )
}

type CacheWrite = { key: string; value: DbRow }

function observeCacheWrites(): { writes: CacheWrite[]; restore: () => void } {
  const writes: CacheWrite[] = []
  const originalSet = Map.prototype.set as any
  let restored = false

  ;(Map.prototype as any).set = function (this: unknown, key: unknown, value: unknown) {
    if (isDbRow(value)) {
      writes.push({ key: String(key), value })
    }
    return originalSet.call(this, key, value)
  }

  const restore = () => {
    if (!restored) {
      restored = true
      ;(Map.prototype as any).set = originalSet
    }
  }

  return { writes, restore }
}

async function withCacheWrites<T>(fn: (writes: CacheWrite[]) => Promise<T>): Promise<T> {
  const observer = observeCacheWrites()
  try {
    return await fn(observer.writes)
  } finally {
    observer.restore()
  }
}

