   - **Minimal fix:** Introduce a nonterminal stopping marker / in-flight promise, and only set terminal `'stopped'` and remove after successful kill/persist or persist a retryable tombstone:
     ```ts
     if (run.stopping) return run.stopPromise; // conceptual guard
     run.stopping = true;
     run.stopPromise = (async () => {
       run.proc.kill();
       await db.update(id, { state: 'stopped' });
       run.state = 'stopped';
       if (runs.get(id) === run) runs.delete(id);
     })();
