       const run = runs.get(id);
       if (!run) return;

       run.state = 'stopped'; // or tombstone/retry entry, depending on policy

       void Promise.resolve(db.update(id, { state: 'stopped' }))
         .catch(err => /* retry/log/queue stop update */)
